Example:

```js
posthog.init('[your api key]', {
    api_host: 'https://posthog.[your-domain].com',
    loaded: function(posthog) {
        posthog.identify('[user unique id]');

        posthog.group('company_id', 'id:5');
        posthog.group('playlist', 'id:77', {
            length: 77,
            some: 'properties'
